    /// <summary>
    /// Make thread count mandatory in the UI
    /// </summary>
    public void postBuild()
    {
        super();

        // make thread count manadatory
        DialogField dialogFieldThreadCount = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(METCBCTInvoicePostingContract, parmThreadCount));
        dialogFieldThreadCount.fieldControl().mandatory(true);
    }
